// === Tab: mySketch.js ===
// Falling 🍂 #WCCChallenge 
// Pixel Collapse - ZRNOF
//
// No third-party libraries today... (except openprocessing_sketch.js?)
// All photos were taken in Taiwan❤️.
//
// Most of my WebGL2 knowledge comes from Andrew Adamson's tutorial videos (Big Thanks!)
// Playlist: https://www.youtube.com/playlist?list=PLPbmjY2NVO_X1U1JzLxLDdRn4NmtxyQQo

const main = async () => {
	const image = await loadImage(getRandomImage())

	// canvas
	const canvasWebGL2 = document.getElementById("canvasWebGL2")
	const canvas2D = document.getElementById("canvas2D")

	// webgl2 setup
	const gl = canvasWebGL2.getContext("webgl2")
	const program = gl.createProgram()
	setShader(gl, program, vert, frag)
	gl.linkProgram(program)
	gl.useProgram(program)

	// resize
	resizeFitContain(image, canvas2D, canvasWebGL2, gl, 0.95)
	window.addEventListener("resize", () => {
		resizeFitContain(image, canvas2D, canvasWebGL2, gl, 0.95)
	})

	// set point size
	const pointSize = [1, 3, 5, 7, 9][floor(random(0, 5))]
	const pointSizeLoc = gl.getUniformLocation(program, "uPointSize")
	gl.uniform1f(pointSizeLoc, pointSize)

	// buffer data
	let positionData = []
	let offsetData = []
	let texCoordData = []

	// generate buffer data
	const cols = image.width / pointSize
	const rows = image.height / pointSize
	const [xOff, yOff] = [2 / cols, 2 / rows]
	const [uOff, vOff] = [1 / cols, 1 / rows]
	// noprotect
	for (let col = 0; col < cols; col++) {
		for (let row = 0; row < rows; row++) {
			positionData.push(-1 + xOff * col + 1 / cols)
			positionData.push(1 - yOff * row - 1 / rows)
			offsetData.push(random(-1, 1))
			offsetData.push(random(-1, 1))
			texCoordData.push((col + 1 / cols) * uOff)
			texCoordData.push((row + 1 / rows) * vOff)
		}
	}

	// set attribute
	setAttributeVec2(gl, program, "aPosition", positionData)
	setAttributeVec2(gl, program, "aOffset", offsetData)
	setAttributeVec2(gl, program, "aTexCoord", texCoordData)

	// set texture
	const imageTexture = gl.createTexture()
	gl.bindTexture(gl.TEXTURE_2D, imageTexture)
	gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, image.width, image.height, 0, gl.RGB, gl.UNSIGNED_BYTE, image)
	gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST)
	gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST)

	// set time
	let time = 0
	const timeLoc = gl.getUniformLocation(program, "uTime")

	// draw call
	const draw = () => {
		//gl.flush()
		gl.clearColor(0, 0, 0, 0.5)
		gl.clear(gl.COLOR_BUFFER_BIT)
		gl.uniform1f(timeLoc, time) // time
		gl.drawArrays(gl.POINTS, 0, cols * rows)
		time += 0.02
		drawImage(canvasWebGL2, canvas2D)
		window.requestAnimationFrame(draw)
	}

	draw()
}

main()


// === Tab: shaderSource.js ===
const vert = `#version 300 es

	in vec2 aPosition;
	in vec2 aOffset;
	in vec2 aTexCoord;

	uniform float uPointSize;
	uniform float uTime;

	out vec2 vTexCoord;
	void main() {
		vTexCoord = aTexCoord;
		vec2 pos = aPosition;
		const float scale = 1.;
		const vec2 speed = vec2(.03, .1);
		pos.x += speed.x*sin(uTime+aOffset.x*100.)*clamp(uTime*0.05, 0., 1.);
		pos.y -= speed.y*scale*abs(aOffset.y)*(1.001-0.5*(pos.y+1.))*pow(uTime, 3.);
		gl_Position = vec4(pos, 0., 1.);
		gl_PointSize = clamp(uPointSize*abs(aOffset.x), 2., uPointSize);
	}
`

const frag = `#version 300 es
	precision mediump float;

	in vec2 vTexCoord;

	uniform sampler2D uImage;

	out vec4 fragColor;
	void main() {
		vec2 uv = vTexCoord;
		fragColor = texture(uImage, uv);
	}
`


// === Tab: tools.js ===
// floor
const floor = (_value) => {
	return Math.floor(_value)
}

// random in range _min to _max
const random = (_min = 0, _max = 1) => {
	return Math.random() * (_max - _min) + _min
}

// load image from _src
const loadImage = (_src) => {
	return new Promise((resolve) => {
		var image = new Image()
		image.addEventListener("load", () => resolve(image))
		image.crossOrigin = "anonymous"
		image.src = _src
	})
}

// get random image url from https://github.com/ZRNOF/Photos-for-image-processing
const getRandomImage = () => {
	const imageList = [
		"Rain_Window_01.jpg",
		"Flower_01.jpg",
		"Flower_03.jpg",
		"Sheet_Music_01.jpg",
		"Sunset_01.jpg",
		"Sunset_02.jpg",
		"Piano_01.jpg",
		"Plant_01.jpg",
		"Beimen_Crystal_Church_01.jpg",
		"The_Dome_of_Light_02.jpg",
		"The_Dome_of_Light_01.jpg",
		"Centipede_01.jpg",
	]
	const index = floor(random(0, imageList.length))
	const filename = imageList[index]
	return `https://raw.githubusercontent.com/ZRNOF/Photos-for-image-processing/main/Package/${filename}`
}

// draw _drawCanvas to _toCanvas
const drawImage = (_drawCanvas, _toCanvas) => {
	const ctx = _toCanvas.getContext("2d")
	ctx.drawImage(_drawCanvas, 0, 0)
}

// resize canvas and gl viewport
const resizeCanvas = (_canvas, _gl, _width, _height) => {
	_canvas.width = _width
	_canvas.height = _height
	_gl.viewport(0, 0, _canvas.width, _canvas.height)
}

// make all fit contain window
const resizeFitContain = (_image, _canvas2D, _canvasWebGL2, _gl, _scale) => {
	const imageAspectRatio = _image.width / _image.height
	const windowAspectRatio = window.innerWidth / window.innerHeight

	if (imageAspectRatio > windowAspectRatio) {
		const baseSize = window.innerWidth * _scale
		resizeCanvas(_canvasWebGL2, _gl, baseSize, baseSize / imageAspectRatio)
		resizeCanvas(_canvas2D, _gl, baseSize, baseSize / imageAspectRatio)
	} else {
		var baseSize = window.innerHeight * _scale
		resizeCanvas(_canvasWebGL2, _gl, baseSize * imageAspectRatio, baseSize)
		resizeCanvas(_canvas2D, _gl, baseSize * imageAspectRatio, baseSize)
	}
}

// set vertex shader and fragment shader
const setShader = (_gl, _program, _vert, _frag) => {
	const vertexShader = _gl.createShader(_gl.VERTEX_SHADER)
	_gl.shaderSource(vertexShader, _vert)
	_gl.compileShader(vertexShader)
	_gl.attachShader(_program, vertexShader)

	const fragmentShader = _gl.createShader(_gl.FRAGMENT_SHADER)
	_gl.shaderSource(fragmentShader, _frag)
	_gl.compileShader(fragmentShader)
	_gl.attachShader(_program, fragmentShader)
}

// set vec2 attribute
const setAttributeVec2 = (_gl, _program, _name, _data) => {
	const bufferData = new Float32Array(_data)
	const location = _gl.getAttribLocation(_program, _name)
	const buffer = _gl.createBuffer()
	_gl.bindBuffer(_gl.ARRAY_BUFFER, buffer)
	_gl.bufferData(_gl.ARRAY_BUFFER, bufferData, _gl.STATIC_DRAW)
	_gl.vertexAttribPointer(location, 2, _gl.FLOAT, false, 0, 0)
	_gl.enableVertexAttribArray(location)
}

